# taken from
# https://stackoverflow.com/questions/492519/timeout-on-a-function-call
@contextmanager
def timeout(duration, formula):
  def timeout_handler(signum, frame):
  raise Exception(f"'{formula}': timed out after {duration} seconds")

  signal.signal(signal.SIGALRM, timeout_handler)
  signal.alarm(duration)
  yield
  signal.alarm(0)


def eval_with_timeout(formula, max_time=3):
  try:
  with timeout(max_time, formula):
  return eval(formula)
  except Exception as e:
  signal.alarm(0)
  print(f"Warning: Failed to eval {formula}, exception: {e}")
  return None


def use_calculator(sample):
  if "<<" not in sample:
  return None

  parts = sample.split("<<")
  remaining = parts[-1]
  if ">>" in remaining:
  return None
  if "=" not in remaining:
  return None
  lhs = remaining.split("=")[0]
  lhs = lhs.replace(",", "")
  if any([x not in "0123456789*+-/.()" for x in lhs]):
  return None
  return eval_with_timeout(lhs)


def sample(model, qn, tokenizer, device, sample_len):
  # Inefficient version of calculator sampling -- no batches, doesn't
  # cache activations from previous tokens
  EQUALS_TOKENS = set([28, 796, 47505])

  for _ in range(sample_len):
  with th.no_grad():
  toks = tokenizer([qn], padding=False, return_tensors="pt").to(device)
  orig_len = toks["input_ids"].shape[1]

  out = model.generate(
  **toks, max_length=orig_len + 1, pad_token_id=model.config.eos_token_id
  )
  text = tokenizer.batch_decode(out)[0]

  if out[0, -1].item() in EQUALS_TOKENS:
  answer = use_calculator(text)
  if answer is not None:
  print("Triggered calculator, answer", answer)
  text = text + str(answer) + ">>"

  qn = text
  return qn

class UserList(_collections_abc.MutableSequence):
  """A more or less complete user-defined wrapper around list objects."""

  def __init__(self, initlist=None):
  self.data = []
  if initlist is not None:
  # XXX should this accept an arbitrary sequence?
  if type(initlist) == type(self.data):
  self.data[:] = initlist
  elif isinstance(initlist, UserList):
  self.data[:] = initlist.data[:]
  else:
  self.data = list(initlist)

  def __repr__(self):
  return repr(self.data)

  def __lt__(self, other):
  return self.data < self.__cast(other)

  def __le__(self, other):
  return self.data <= self.__cast(other)

  def __eq__(self, other):
  return self.data == self.__cast(other)

  def __gt__(self, other):
  return self.data > self.__cast(other)

  def __ge__(self, other):
  return self.data >= self.__cast(other)

  def __cast(self, other):
  return other.data if isinstance(other, UserList) else other

  def __contains__(self, item):
  return item in self.data

  def __len__(self):
  return len(self.data)

  def __getitem__(self, i):
  if isinstance(i, slice):
  return self.__class__(self.data[i])
  else:
  return self.data[i]

  def __setitem__(self, i, item):
  self.data[i] = item

  def __delitem__(self, i):
  del self.data[i]

  def __add__(self, other):
  if isinstance(other, UserList):
  return self.__class__(self.data + other.data)
  elif isinstance(other, type(self.data)):
  return self.__class__(self.data + other)
  return self.__class__(self.data + list(other))

  def __radd__(self, other):
  if isinstance(other, UserList):
  return self.__class__(other.data + self.data)
  elif isinstance(other, type(self.data)):
  return self.__class__(other + self.data)
  return self.__class__(list(other) + self.data)

  def __iadd__(self, other):
  if isinstance(other, UserList):
  self.data += other.data
  elif isinstance(other, type(self.data)):
  self.data += other
  else:
  self.data += list(other)
  return self

  def __mul__(self, n):
  return self.__class__(self.data * n)

  __rmul__ = __mul__

  def __imul__(self, n):
  self.data *= n
  return self

  def __copy__(self):
  inst = self.__class__.__new__(self.__class__)
  inst.__dict__.update(self.__dict__)
  # Create a copy and avoid triggering descriptors
  inst.__dict__["data"] = self.__dict__["data"][:]
  return inst

  def append(self, item):
  self.data.append(item)

  def insert(self, i, item):
  self.data.insert(i, item)

  def pop(self, i=-1):
  return self.data.pop(i)

  def remove(self, item):
  self.data.remove(item)

  def clear(self):
  self.data.clear()

  def copy(self):
  return self.__class__(self)

  def count(self, item):
  return self.data.count(item)

  def index(self, item, *args):
  return self.data.index(item, *args)

  def reverse(self):
  self.data.reverse()

  def sort(self, /, *args, **kwds):
  self.data.sort(*args, **kwds)

  def extend(self, other):
  if isinstance(other, UserList):
  self.data.extend(other.data)
  else:
  self.data.extend(other)

def fmean(data, weights=None):
  """Convert data to floats and compute the arithmetic mean.

  This runs faster than the mean() function and it always returns a float.
  If the input dataset is empty, it raises a StatisticsError.

  >>> fmean([3.5, 4.0, 5.25])
  4.25
  """
  try:
  n = len(data)
  except TypeError:
  # Handle iterators that do not define __len__().
  n = 0
  def count(iterable):
  nonlocal n
  for n, x in enumerate(iterable, start=1):
  yield x
  data = count(data)
  if weights is None:
  total = fsum(data)
  if not n:
  raise StatisticsError('fmean requires at least one data point')
  return total / n
  try:
  num_weights = len(weights)
  except TypeError:
  weights = list(weights)
  num_weights = len(weights)
  num = fsum(map(mul, data, weights))
  if n != num_weights:
  raise StatisticsError('data and weights must be the same length')
  den = fsum(weights)
  if not den:
  raise StatisticsError('sum of weights must be non-zero')
  return num / den

def bisect_right(a, x, lo=0, hi=None, *, key=None):
  """Return the index where to insert item x in list a, assuming a is sorted.

  The return value i is such that all e in a[:i] have e <= x, and all e in
  a[i:] have e > x.  So if x already appears in the list, a.insert(i, x) will
  insert just after the rightmost x already there.

  Optional args lo (default 0) and hi (default len(a)) bound the
  slice of a to be searched.
  """

  if lo < 0:
  raise ValueError('lo must be non-negative')
  if hi is None:
  hi = len(a)
  # Note, the comparison uses "<" to match the
  # __lt__() logic in list.sort() and in heapq.
  if key is None:
  while lo < hi:
  mid = (lo + hi) // 2
  if x < a[mid]:
  hi = mid
  else:
  lo = mid + 1
  else:
  while lo < hi:
  mid = (lo + hi) // 2
  if x < key(a[mid]):
  hi = mid
  else:
  lo = mid + 1
  return lo

class _EnumDict(dict):
  """
  Track enum member order and ensure member names are not reused.

  EnumType will use the names found in self._member_names as the
  enumeration member names.
  """
  def __init__(self):
  super().__init__()
  self._member_names = {} # use a dict to keep insertion order
  self._last_values = []
  self._ignore = []
  self._auto_called = False

  def __setitem__(self, key, value):
  """
  Changes anything not dundered or not a descriptor.

  If an enum member name is used twice, an error is raised; duplicate
  values are not checked for.

  Single underscore (sunder) names are reserved.
  """
  if _is_internal_class(self._cls_name, value):
  import warnings
  warnings.warn(
  "In 3.13 classes created inside an enum will not become a member.  "
  "Use the `member` decorator to keep the current behavior.",
  DeprecationWarning,
  stacklevel=2,
  )
  if _is_private(self._cls_name, key):
  # also do nothing, name will be a normal attribute
  pass
  elif _is_sunder(key):
  if key not in (
  '_order_',
  '_generate_next_value_', '_numeric_repr_', '_missing_', '_ignore_',
  '_iter_member_', '_iter_member_by_value_', '_iter_member_by_def_',
  ):
  raise ValueError(
  '_sunder_ names, such as %r, are reserved for future Enum use'
  % (key, )
  )
  if key == '_generate_next_value_':
  # check if members already defined as auto()
  if self._auto_called:
  raise TypeError("_generate_next_value_ must be defined before members")
  _gnv = value.__func__ if isinstance(value, staticmethod) else value
  setattr(self, '_generate_next_value', _gnv)
  elif key == '_ignore_':
  if isinstance(value, str):
  value = value.replace(',',' ').split()
  else:
  value = list(value)
  self._ignore = value
  already = set(value) & set(self._member_names)
  if already:
  raise ValueError(
  '_ignore_ cannot specify already set names: %r'
  % (already, )
  )
  elif _is_dunder(key):
  if key == '__order__':
  key = '_order_'
  elif key in self._member_names:
  # descriptor overwriting an enum?
  raise TypeError('%r already defined as %r' % (key, self[key]))
  elif key in self._ignore:
  pass
  elif isinstance(value, nonmember):
  # unwrap value here; it won't be processed by the below `else`
  value = value.value
  elif _is_descriptor(value):
  pass
  # TODO: uncomment next three lines in 3.13
  # elif _is_internal_class(self._cls_name, value):
  #  # do nothing, name will be a normal attribute
  #  pass
  else:
  if key in self:
  # enum overwriting a descriptor?
  raise TypeError('%r already defined as %r' % (key, self[key]))
  elif isinstance(value, member):
  # unwrap value here -- it will become a member
  value = value.value
  non_auto_store = True
  single = False
  if isinstance(value, auto):
  single = True
  value = (value, )
  if type(value) is tuple and any(isinstance(v, auto) for v in value):
  # insist on an actual tuple, no subclasses, in keeping with only supporting
  # top-level auto() usage (not contained in any other data structure)
  auto_valued = []
  for v in value:
  if isinstance(v, auto):
  non_auto_store = False
  if v.value == _auto_null:
  v.value = self._generate_next_value(
  key, 1, len(self._member_names), self._last_values[:],
  )
  self._auto_called = True
  v = v.value
  self._last_values.append(v)
  auto_valued.append(v)
  if single:
  value = auto_valued[0]
  else:
  value = tuple(auto_valued)
  self._member_names[key] = None
  if non_auto_store:
  self._last_values.append(value)
  super().__setitem__(key, value)

  def update(self, members, **more_members):
  try:
  for name in members.keys():
  self[name] = members[name]
  except AttributeError:
  for name, value in members:
  self[name] = value
  for name, value in more_members.items():
  self[name] = value

class _proto_member:
  """
  intermediate step for enum members between class execution and final creation
  """

  def __init__(self, value):
  self.value = value

  def __set_name__(self, enum_class, member_name):
  """
  convert each quasi-member into an instance of the new enum class
  """
  # first step: remove ourself from enum_class
  delattr(enum_class, member_name)
  # second step: create member based on enum_class
  value = self.value
  if not isinstance(value, tuple):
  args = (value, )
  else:
  args = value
  if enum_class._member_type_ is tuple:  # special case for tuple enums
  args = (args, )  # wrap it one more time
  if not enum_class._use_args_:
  enum_member = enum_class._new_member_(enum_class)
  if not hasattr(enum_member, '_value_'):
  try:
  enum_member._value_ = enum_class._member_type_(*args)
  except Exception as exc:
  enum_member._value_ = value
  else:
  enum_member = enum_class._new_member_(enum_class, *args)
  if not hasattr(enum_member, '_value_'):
  if enum_class._member_type_ is object:
  enum_member._value_ = value
  else:
  try:
  enum_member._value_ = enum_class._member_type_(*args)
  except Exception as exc:
  raise TypeError(
  '_value_ not set in __new__, unable to create it'
  ) from None
  value = enum_member._value_
  enum_member._name_ = member_name
  enum_member.__objclass__ = enum_class
  enum_member.__init__(*args)
  enum_member._sort_order_ = len(enum_class._member_names_)
  # If another member with the same value was already defined, the
  # new member becomes an alias to the existing one.
  try:
  try:
  # try to do a fast lookup to avoid the quadratic loop
  enum_member = enum_class._value2member_map_[value]
  except TypeError:
  for name, canonical_member in enum_class._member_map_.items():
  if canonical_member._value_ == value:
  enum_member = canonical_member
  break
  else:
  raise KeyError
  except KeyError:
  # this could still be an alias if the value is multi-bit and the
  # class is a flag class
  if (
  Flag is None
  or not issubclass(enum_class, Flag)
  ):
  # no other instances found, record this member in _member_names_
  enum_class._member_names_.append(member_name)
  elif (
  Flag is not None
  and issubclass(enum_class, Flag)
  and _is_single_bit(value)
  ):
  # no other instances found, record this member in _member_names_
  enum_class._member_names_.append(member_name)
  # get redirect in place before adding to _member_map_
  # but check for other instances in parent classes first
  need_override = False
  descriptor = None
  for base in enum_class.__mro__[1:]:
  descriptor = base.__dict__.get(member_name)
  if descriptor is not None:
  if isinstance(descriptor, (property, DynamicClassAttribute)):
  break
  else:
  need_override = True
  # keep looking for an enum.property
  if descriptor and not need_override:
  # previous enum.property found, no further action needed
  pass
  elif descriptor and need_override:
  redirect = property()
  redirect.__set_name__(enum_class, member_name)
  # Previous enum.property found, but some other inherited attribute
  # is in the way; copy fget, fset, fdel to this one.
  redirect.fget = descriptor.fget
  redirect.fset = descriptor.fset
  redirect.fdel = descriptor.fdel
  setattr(enum_class, member_name, redirect)
  else:
  setattr(enum_class, member_name, enum_member)
  # now add to _member_map_ (even aliases)
  enum_class._member_map_[member_name] = enum_member
  try:
  # This may fail if value is not hashable. We can't add the value
  # to the map, and by-value lookups for this value will be
  # linear.
  enum_class._value2member_map_.setdefault(value, enum_member)
  except TypeError:
  # keep track of the value in a list so containment checks are quick
  enum_class._unhashable_values_.append(value)

class ChainMap(_collections_abc.MutableMapping):
  ''' A ChainMap groups multiple dicts (or other mappings) together
  to create a single, updateable view.

  The underlying mappings are stored in a list.  That list is public and can
  be accessed or updated using the *maps* attribute.  There is no other
  state.

  Lookups search the underlying mappings successively until a key is found.
  In contrast, writes, updates, and deletions only operate on the first
  mapping.

  '''

  def __init__(self, *maps):
  '''Initialize a ChainMap by setting *maps* to the given mappings.
  If no mappings are provided, a single empty dictionary is used.

  '''
  self.maps = list(maps) or [{}]  # always at least one map

  def __missing__(self, key):
  raise KeyError(key)

  def __getitem__(self, key):
  for mapping in self.maps:
  try:
  return mapping[key]  # can't use 'key in mapping' with defaultdict
  except KeyError:
  pass
  return self.__missing__(key)  # support subclasses that define __missing__

  def get(self, key, default=None):
  return self[key] if key in self else default

  def __len__(self):
  return len(set().union(*self.maps))  # reuses stored hash values if possible

  def __iter__(self):
  d = {}
  for mapping in reversed(self.maps):
  d.update(dict.fromkeys(mapping))  # reuses stored hash values if possible
  return iter(d)

  def __contains__(self, key):
  return any(key in m for m in self.maps)

  def __bool__(self):
  return any(self.maps)

  @_recursive_repr()
  def __repr__(self):
  return f'{self.__class__.__name__}({", ".join(map(repr, self.maps))})'

  @classmethod
  def fromkeys(cls, iterable, *args):
  'Create a ChainMap with a single dict created from the iterable.'
  return cls(dict.fromkeys(iterable, *args))

  def copy(self):
  'New ChainMap or subclass with a new copy of maps[0] and refs to maps[1:]'
  return self.__class__(self.maps[0].copy(), *self.maps[1:])

  __copy__ = copy

  def new_child(self, m=None, **kwargs):  # like Django's Context.push()
  '''New ChainMap with a new map followed by all previous maps.
  If no map is provided, an empty dict is used.
  Keyword arguments update the map or new empty dict.
  '''
  if m is None:
  m = kwargs
  elif kwargs:
  m.update(kwargs)
  return self.__class__(m, *self.maps)

  @property
  def parents(self):  # like Django's Context.pop()
  'New ChainMap from maps[1:].'
  return self.__class__(*self.maps[1:])

  def __setitem__(self, key, value):
  self.maps[0][key] = value

  def __delitem__(self, key):
  try:
  del self.maps[0][key]
  except KeyError:
  raise KeyError(f'Key not found in the first mapping: {key!r}')

  def popitem(self):
  'Remove and return an item pair from maps[0]. Raise KeyError is maps[0] is empty.'
  try:
  return self.maps[0].popitem()
  except KeyError:
  raise KeyError('No keys found in the first mapping.')

  def pop(self, key, *args):
  'Remove *key* from maps[0] and return its value. Raise KeyError if *key* not in maps[0].'
  try:
  return self.maps[0].pop(key, *args)
  except KeyError:
  raise KeyError(f'Key not found in the first mapping: {key!r}')

  def clear(self):
  'Clear maps[0], leaving maps[1:] intact.'
  self.maps[0].clear()

  def __ior__(self, other):
  self.maps[0].update(other)
  return self

  def __or__(self, other):
  if not isinstance(other, _collections_abc.Mapping):
  return NotImplemented
  m = self.copy()
